  drawKeyline(ctx, w, h) {
    ctx.save();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
    ctx.lineWidth = Math.max(1, Math.min(w, h) * 0.003);
    ctx.strokeRect(
      ctx.lineWidth / 2, ctx.lineWidth / 2,
      w - ctx.lineWidth, h - ctx.lineWidth
    );
    ctx.restore();
