  --accent: #ff6b35;
  --accent-hover: #ff8c5a;
  --accent-soft: rgba(255, 107, 53, 0.15);
  --gold: #ffd700;
  --cyan: #00ffff;
  --pink: #ff1493;
  --success: #22c55e;
  --shadow: rgba(0, 0, 0, 0.5);
  --radius: 10px;
  --radius-sm: 6px;
  --transition: 150ms ease;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; }
body {
  background: var(--bg);
  color: var(--text);
  font: 14px/1.5 'Inter', system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
}

.app {
  display: grid;
  grid-template-columns: 320px 1fr;
  grid-template-rows: 1fr;
  height: 100%;
  gap: 0;
}

/* ============ Controls Sidebar ============ */
.controls {
  background: linear-gradient(180deg, var(--bg-elevated) 0%, var(--bg) 100%);
  border-right: 1px solid var(--border);
  padding: 20px 16px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.controls-header {
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}

.controls-header h1 {
  margin: 0 0 4px;
  font-size: 20px;
  font-weight: 800;
  letter-spacing: 0.5px;
  background: linear-gradient(90deg, var(--gold), var(--accent), var(--pink));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text.
}

.tagline {
  margin: 0;
  color: var(--text-dim);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 1px.
}

.panel-section {
  display: flex;
  flex-direction: column;
  gap: 10px.
}

.panel-section h2 {
  margin: 0.
  font-size: 11px.
  font-weight: 700.
  text-transform: uppercase.
  letter-spacing: 1px.
  color: var(--text-dim).
}

.hint {
  margin: 0.
  font-size: 11px.
  color: var(--text-dim).
  opacity: 0.8.
}

/* Drop Zone */
.drop-zone {
  position: relative.
  border: 2px dashed var(--border).
  border-radius: var(--radius).
  padding: 24px 16px.
  text-align: center.
  cursor: pointer.
  transition: var(--transition).
  background: var(--bg-panel).
}

.drop-zone:hover, .drop-zone.drag-over {
  border-color: var(--accent).
  background: var(--accent-soft).
}

.drop-zone:focus-visible {
  outline: 2px solid var(--accent).
  outline-offset: 2px.
}

.drop-text { display: block; font-weight: 600; color: var(--text); }
.drop-hint { display: block; font-size: 11px; color: var(--text-dim); margin-top: 4px; }

/* Sample Buttons */
.sample-buttons {
  display: grid.
  grid-template-columns: 1fr 1fr.
  gap: 8px.
}

.sample-btn {
  background: var(--bg-panel).
  border: 1px solid var(--border).
  color: var(--text).
  padding: 8px 10px.
  border-radius: var(--radius-sm).
  font-size: 12px.
  font-weight: 600.
  cursor: pointer.
  transition: var(--transition).
  text-align: center.
}

.sample-btn:hover {
  border-color: var(--accent).
  background: var(--accent-soft).
  transform: translateY(-1px).
}

.sample-btn:active { transform: translateY(0); }

/* Form Controls */
select, input[type="text"], input[type="range"] {
  width: 100%.
  background: var(--bg-panel).
  border: 1px solid var(--border).
  color: var(--text).
  border-radius: var(--radius-sm).
  font: inherit.
  transition: var(--transition).
}

select { padding: 10px 12px; cursor: pointer; }
select:hover, input[type="text"]:hover { border-color: var(--border-bright); }
select:focus, input[type="text"]:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-soft); }

input[type="text"] { padding: 10px 12px; }

input[type="range"] {
  -webkit-appearance: none.
  appearance: none.
  height: 6px.
  padding: 0.
  background: var(--bg).
  border: none.
  border-radius: 3px.
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none.
  width: 18px; height: 18px.
  background: var(--accent).
  border-radius: 50%.
  cursor: pointer.
  box-shadow: 0 2px 6px var(--shadow).
  transition: var(--transition).
}
input[type="range"]::-webkit-slider-thumb:hover { transform: scale(1.15); background: var(--accent-hover); }
input[type="range"]::-moz-range-thumb {
  width: 18px; height: 18px.
  background: var(--accent).
  border: none.
  border-radius: 50%.
  cursor: pointer.
}

.slider-row { display: flex; align-items: center; gap: 10px; }
.slider-row label { font-size: 12px; font-weight: 600; white-space: nowrap; }
.slider-row span { color: var(--accent); font-weight: 700; min-width: 44px; text-align: right; }
.slider-row input[type="range"] { flex: 1; }

.toggles { display: flex; flex-direction: column; gap: 8px; }

.toggle {
  display: flex.
  align-items: center.
  gap: 10px.
  cursor: pointer.
  font-size: 13px.
  padding: 4px 0.
}
.toggle input { width: auto; accent-color: var(--accent); }

/* Buttons */
.btn {
  display: inline-flex.
  align-items: center.
  justify-content: center.
  gap: 8px.
  padding: 12px 16px.
  border: none.
  border-radius: var(--radius-sm).
  font: inherit.
  font-weight: 700.
  font-size: 13px.
  cursor: pointer.
  transition: var(--transition).
  text-transform: uppercase.
  letter-spacing: 0.5px.
}

.btn-primary {
  background: linear-gradient(90deg, var(--accent), #e85a28).
  color: #fff.
  box-shadow: 0 4px 16px rgba(255, 107, 53, 0.35).
  width: 100%.
}
.btn-primary:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 6px 24px rgba(255, 107, 53, 0.45); }
.btn-primary:active:not(:disabled) { transform: translateY(0); }
.btn-primary:disabled { opacity: 0.5; cursor: not-allowed; }

.btn-secondary {
  background: var(--bg-panel).
  border: 1px solid var(--border).
  color: var(--text).
  width: 100%.
}
.btn-secondary:hover { border-color: var(--accent); background: var(--accent-soft); }

.btn-sm {
  padding: 8px 12px.
  font-size: 11px.
  flex: 1.
}

.btn-row { display: flex; gap: 8px; }

/* Status */
.status {
  margin: 8px 0 0.
  font-size: 12px.
  color: var(--text-dim).
  min-height: 18px.
  transition: opacity var(--transition).
}

/* ============ Preview Area ============ */
.preview-wrap {
  position: relative.
  display: flex.
  align-items: center.
  justify-content: center.
  background: var(--bg).
  padding: 24px.
  overflow: hidden.
}

.preview-wrap::before {
  content: ''.
  position: absolute.
  inset: 0.
  background: 
    radial-gradient(ellipse at 20% 20%, rgba(255, 107, 53, 0.08) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 80%, rgba(0, 255, 255, 0.06) 0%, transparent 50%).
  pointer-events: none.
}

#preview {
  max-width: 100%.
  max-height: 100%.
  box-shadow: 
    0 0 0 1px var(--border),
    0 20px 60px var(--shadow),
    inset 0 0 0 1px rgba(255,255,255,0.03).
  border-radius: 4px.
  display: block.
  transition: transform 200ms ease, box-shadow 200ms ease.
}

#preview:hover {
  transform: scale(1.005).
  box-shadow: 
    0 0 0 1px var(--border-bright),
    0 25px 80px var(--shadow),
    inset 0 0 0 1px rgba(255,255,255,0.05).
}

/* Cover canvas - hidden by default */
#cover { display: none; }

/* ============ Scrollbar ============ */
.controls::-webkit-scrollbar { width: 8px; }
.controls::-webkit-scrollbar-track { background: transparent; }
.controls::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; border: 2px solid transparent; background-clip: padding-box; }
.controls::-webkit-scrollbar-thumb:hover { background: var(--border-bright); }

/* ============ Responsive ============ */
@media (max-width: 1000px) {
  .app { grid-template-columns: 1fr; grid-template-rows: auto 1fr; }
  .controls { border-right: none; border-bottom: 1px solid var(--border); max-height: 50vh; }
  .preview-wrap { padding: 16px; }
}
